export default ({ pages, prior, record }) => {
  const index = prior ? prior.index + 1 : 0;
  const results =
    prior && record?.index === prior.index ? [...prior.results, record] : (prior?.results ?? []);
  const page = pages[index] ?? null;
  return { cursor: { index, results }, page, results, more: Boolean(page) };
};

